            controls.setReturningAttributes(null); // return all attributes

            NamingEnumeration<SearchResult> results = ctx.search(baseDN, searchFilter, controls);

            boolean found = false;
            while (results.hasMore()) {
                found = true;
                SearchResult sr = results.next();
                result.append(formatSearchResult(sr));
            }

            if (!found) {
                result.append("User not found: ").append(username);
            }

        } catch (NamingException e) {
            result.append("LDAP Error: ").append(e.toString());
        } finally {
            if (ctx != null) {
                try {
                    ctx.close();
                } catch (NamingException e) {
                    // ignore
                }
            }
        }

        return result.toString();
    }

    public static String constructBaseDN(String domain) {
        if (domain == null || domain.isEmpty()) {
            return "";
        }
        // If already in DN format, return as is
        if (domain.toLowerCase().startsWith("dc=")) {
            return domain;
        }
        // Convert domain.com to dc=domain,dc=com
        String[] parts = domain.split("\\.");
        StringBuilder dn = new StringBuilder();
        for (int i = 0; i < parts.length; i++) {
            if (i > 0) dn.append(",");
            dn.append("dc=").append(parts[i].trim());
        }
        return dn.toString();
    }

    public static String constructSearchFilter(String username) {
        return "(uid=" + escapeLDAPSearchFilter(username) + ")";
    }

    private static String escapeLDAPSearchFilter(String input) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            switch (c) {
                case '\\':
                    sb.append("\\5c");
                    break;
                case '*':
                    sb.append("\\2a");
                    break;
                case '(':
                    sb.append("\\28");
                    break;
                case ')':
                    sb.append("\\29");
                    break;
                case '\u0000':
                    sb.append("\\00");
                    break;
                default:
                    sb.append(c);
            }
        }
        return sb.toString();
    }

    private static String formatSearchResult(SearchResult sr) throws NamingException {
        StringBuilder sb = new StringBuilder();
        sb.append("DN: ").append(sr.getNameInNamespace()).append("\n");

        Attributes attrs = sr.getAttributes();
        if (attrs != null) {
            NamingEnumeration<? extends Attribute> attrEnum = attrs.getAll();
            while (attrEnum.hasMore()) {
                Attribute attr = attrEnum.next();
                sb.append(attr.getID()).append(": ");
                NamingEnumeration<?> values = attr.getAll();
                boolean first = true;
                while (values.hasMore()) {
                    if (!first) sb.append(", ");
                    sb.append(values.next());
                    first = false;
                }
                sb.append("\n");
            }
        }
        sb.append("\n");
        return sb.toString();
    }
